// =============================================================================
//  apps/compare_planners.cpp   ->   the `mtlc_compare` tool (MTLC_BUILD_COMPARE)
//
//  Head-to-head: cpp_planner's mtl::Planner (discrete orienteering + Dubins +
//  gimbal schedule) against mtl::curve::Planner on the SAME scenario, scored by
//  the SAME residual-belief code.
//
//    ./mtlc_compare [--seeds 21,1,2,3,4,5] [--cell-size M] [--stagger M] [--quiet]
//
//  The scenario is generated by each package's own mapgen (the curve package's
//  is a copy), and the tool asserts the two priors are bit-identical before
//  planning.  Each plan is scored with mtl::eval::computeResidualBelief; the
//  curve plan is also scored with the copied mtl::curve::eval version, and the
//  two must agree (they are the same code).
// =============================================================================
#include <chrono>
#include <cstdio>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

#include "mtl/eval/detection.hpp"
#include "mtl/mapgen/scenario.hpp"
#include "mtl/planner.hpp"
#include "mtl_curve/eval/detection.hpp"
#include "mtl_curve/mapgen/scenario.hpp"
#include "mtl_curve/planner.hpp"

namespace mc = mtl::curve;

int main(int argc, char** argv) {
    std::vector<std::uint64_t> seeds = {21, 1, 2, 3, 4, 5};
    double cellSize = 1.0;
    double stagger = 25.0;
    bool quiet = false;
    for (int i = 1; i < argc; ++i) {
        const std::string arg = argv[i];
        if (arg == "--seeds" && i + 1 < argc) {
            seeds.clear();
            std::stringstream ss(argv[++i]);
            std::string tok;
            while (std::getline(ss, tok, ',')) seeds.push_back(std::stoull(tok));
        } else if (arg == "--cell-size" && i + 1 < argc) {
            cellSize = std::stod(argv[++i]);
        } else if (arg == "--stagger" && i + 1 < argc) {
            stagger = std::stod(argv[++i]);
        } else if (arg == "--quiet") {
            quiet = true;
        } else {
            std::cerr << "usage: mtlc_compare [--seeds a,b,c] [--cell-size M] [--stagger M] [--quiet]\n";
            return 2;
        }
    }

    std::printf("%6s %12s %8s %12s %8s %8s %9s %9s\n", "seed", "mtl resid", "mtl det", "curve resid", "crv det",
                "change", "mtl [s]", "curve [s]");
    double sumA = 0.0, sumB = 0.0;
    int bad = 0;
    for (const std::uint64_t seed : seeds) {
        // ---- the scenario, from both packages ----------------------------------
        mtl::PlannerParams pa;
        pa.rngSeed = seed;
        pa.cellSize = cellSize;
        pa.verbose = false;
        pa.verifyGeometryVerbose = false;
        mc::PlannerParams pb;
        pb.rngSeed = seed;
        pb.cellSize = cellSize;
        pb.verbose = !quiet;
        pb.team.altitudeStagger = stagger;

        const mtl::BeliefField ba = mtl::mapgen::generateBeliefMap(pa.mapSize, pa.cellSize, mtl::BeliefMapParams{}, seed);
        const mc::BeliefField bb = mc::mapgen::generateBeliefMap(pb.mapSize, pb.cellSize, mc::BeliefMapParams{}, seed);
        if ((ba.values - bb.values).cwiseAbs().maxCoeff() != 0.0) {
            std::cerr << "seed " << seed << ": the two priors differ - the mapgen copy has drifted\n";
            ++bad;
            continue;
        }
        std::vector<mtl::Target> ta = mtl::mapgen::generateTargetPoses(ba, 50, seed + 1);
        std::vector<mc::Target> tb = mc::mapgen::generateTargetPoses(bb, 50, seed + 1);

        std::vector<mtl::Vec2> sa;
        std::vector<mc::Vec2> sb;
        for (int a = 0; a < 3; ++a) {
            sa.emplace_back(2000.0 + a, 2000.0 + a);
            sb.emplace_back(2000.0 + a, 2000.0 + a);
        }

        // ---- plan -----------------------------------------------------------
        auto t0 = std::chrono::steady_clock::now();
        mtl::Planner A(pa);
        const mtl::PlanningResult ra = A.plan(ba, sa);
        const double secA = std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();
        t0 = std::chrono::steady_clock::now();
        mc::Planner B(pb);
        const mc::PlanningResult rb = B.plan(bb, sb);
        const double secB = std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();

        // ---- score: the same residual code for both ---------------------------
        const mtl::eval::ResidualBelief resA = mtl::eval::computeResidualBelief(ba, ra.trajectories, pa.fov, pa.sensor);
        std::vector<mtl::AgentTrajectory> asMtl(rb.trajectories.size());
        for (std::size_t a = 0; a < rb.trajectories.size(); ++a) {
            asMtl[a].drone = rb.trajectories[a].drone;
            asMtl[a].sensor = rb.trajectories[a].sensor;
            asMtl[a].rpy = rb.trajectories[a].rpy;
        }
        const mtl::eval::ResidualBelief resB = mtl::eval::computeResidualBelief(ba, asMtl, pa.fov, pa.sensor);
        const mc::eval::ResidualBelief resB2 = mc::eval::computeResidualBelief(bb, rb.trajectories, pb.fov, pb.sensor);
        if (std::abs(resB.residualMass - resB2.residualMass) > 1e-12) {
            std::cerr << "seed " << seed << ": the eval copy disagrees with cpp_planner's ("
                      << resB.residualMass << " vs " << resB2.residualMass << ")\n";
            ++bad;
        }
        mtl::eval::updateTargetDetectionProbs(ra.trajectories, ra.timeVec, ta, pa.fov, pa.sensor, pa.detectionThreshold);
        mc::eval::updateTargetDetectionProbs(rb.trajectories, rb.timeVec, tb, pb.fov, pb.sensor, pb.detectionThreshold);
        int da = 0, db = 0;
        for (const auto& t : ta) da += t.detected() ? 1 : 0;
        for (const auto& t : tb) db += t.detected() ? 1 : 0;

        std::printf("%6llu %12.6f %8d %12.6f %8d %7.0f%% %9.1f %9.1f\n", static_cast<unsigned long long>(seed),
                    resA.residualMass, da, resB.residualMass, db,
                    100.0 * (resB.residualMass - resA.residualMass) / resA.residualMass, secA, secB);
        std::fflush(stdout);
        sumA += resA.residualMass;
        sumB += resB.residualMass;
    }
    const double n = static_cast<double>(seeds.size());
    std::printf("%6s %12.6f %8s %12.6f %8s %7.0f%%\n", "mean", sumA / n, "", sumB / n, "",
                100.0 * (sumB - sumA) / sumA);
    return bad == 0 ? 0 : 1;
}
